// === NORMALIZADOR DE ENTRADA ===
// Convierte cualquier evento de Telegram (texto o clic de boton)
// en un objeto unico y limpio que el resto del flujo entiende.
const u = $input.first().json;
let chatId='', userId='', firstName='', raw='', isCallback=false, callbackId='', messageId='';

if (u.callback_query) {                       // el usuario toco un boton inline
  isCallback = true;
  chatId    = u.callback_query.message.chat.id;
  userId    = u.callback_query.from.id;
  firstName = u.callback_query.from.first_name || '';
  raw       = (u.callback_query.data || '').trim();
  callbackId= u.callback_query.id;
  messageId = u.callback_query.message.message_id;
} else if (u.message) {                        // el usuario escribio texto
  chatId    = u.message.chat.id;
  userId    = u.message.from.id;
  firstName = u.message.from.first_name || '';
  raw       = (u.message.text || '').trim();
  messageId = u.message.message_id;
}

// Mapeo de comandos de texto a acciones internas
const cmdMap = {'/start':'HOME','/menu':'MENU','/carrito':'CART',
                '/pedidos':'MYORDERS','/estado':'STATUS','/admin':'ADMIN','/pendientes':'ADMIN','/ayuda':'UNKNOWN'};
const actions = ['HOME','MENU','CART','CLEAR','CONFIRM','MYORDERS','STATUS'];

let action='UNKNOWN', arg1='', arg2='';
const low = raw.toLowerCase();

if (cmdMap[low]) {
  action = cmdMap[low];
} else if (raw.includes(':')) {                // botones tipo  CAT:Bebidas  /  ADD:B01:2
  const p = raw.split(':');
  action = p[0].toUpperCase(); arg1 = p[1] || ''; arg2 = p[2] || '';
} else if (actions.includes(raw.toUpperCase())) {
  action = raw.toUpperCase();
} else if (/^[A-Za-z]\d{1,3}(\s+\d{1,3})?$/.test(raw)) {  // texto tipo  "B01 2"
  action = 'ADDITEM';
  const parts = raw.split(/\s+/);
  arg1 = parts[0].toUpperCase();
  arg2 = parts[1] ? String(parseInt(parts[1], 10)) : '1';
}

return [{ json: { chatId, userId: String(userId), firstName, raw,
                  action, arg1, arg2, isCallback, callbackId, messageId } }];

// === CONSTRUIR LISTA DE PRODUCTOS ===
// Optimizacion: la lectura ya viene FILTRADA por categoria desde Sheets,
// asi no traemos toda la base. Aqui solo damos formato.
const cat   = $('Normalizar Entrada').first().json.arg1;
const rows  = $input.all().map(i => i.json);
const icon  = { 'Bebidas':'☕','Comidas':'🍔','Snacks':'🍪' }[cat] || '🍽';
let text = `${icon} <b>${String(cat).toUpperCase()}</b>\n\n`;
const buttons = [];

if (rows.length === 0) {
  text += 'No hay productos en esta categoría por ahora.';
} else {
  for (const p of rows) {
    const agotado = Number(p.stock) <= 0;
    text += `<b>${p.id_producto}</b> · ${p.nombre}\n` +
            `   💲${Number(p.precio).toFixed(2)}` +
            (agotado ? '  —  <i>AGOTADO ❌</i>' : `  —  stock: ${p.stock}`) + '\n\n';
    if (!agotado) buttons.push({ id: p.id_producto, nombre: p.nombre });
  }
  text += '➕ Para pedir, toca un producto o escribe su código y cantidad (ej: <code>B01 2</code>).';
}
return [{ json: { text, buttons, chatId: $('Normalizar Entrada').first().json.chatId } }];

// Convierte la lista de productos disponibles en filas de botones (de a 2).
const d = $input.first().json;
const rows = [];
for (let i = 0; i < d.buttons.length; i += 2) {
  const slice = d.buttons.slice(i, i + 2);
  rows.push({ row: { buttons: slice.map(b => ({ text: `➕ ${b.id}`, additionalFields: { callback_data: `ADD:${b.id}:1` } })) } });
}
rows.push({ row: { buttons: [
  { text: '🛒 Carrito', additionalFields: { callback_data: 'CART' } },
  { text: '🍽 Menú',    additionalFields: { callback_data: 'MENU' } },
]}});
return [{ json: { text: d.text, rows, chatId: d.chatId } }];

// === AGREGAR AL CARRITO ===
const norm = $('Normalizar Entrada').first().json;
const prodRows = $('Leer MENU (item)').all().map(i => i.json);
const prod = prodRows.find(p => String(p.id_producto).toUpperCase() === String(norm.arg1).toUpperCase());

// carrito actual desde la sesion (o vacio)
let cart = [];
const sess = $('Leer Sesión (add)').all().map(i => i.json);
if (sess.length && sess[0].carrito_temporal) {
  try { cart = JSON.parse(sess[0].carrito_temporal); } catch (e) { cart = []; }
}
if (!Array.isArray(cart)) cart = [];

const qty = Math.max(1, parseInt(norm.arg2 || '1', 10));

// VALIDACIONES (branching real)
if (!prod) {
  return [{ json: { ok:false, reason:`❓ No encontré el producto <b>${norm.arg1}</b>. Revisa el código en /menu.`, chatId: norm.chatId } }];
}
const enCarrito = cart.find(c => c.id === prod.id_producto)?.cantidad || 0;
if (Number(prod.stock) < (enCarrito + qty)) {
  return [{ json: { ok:false, reason:`⚠️ No hay stock suficiente de <b>${prod.nombre}</b> (disponible: ${prod.stock}).`, chatId: norm.chatId } }];
}

// agregar / sumar
const found = cart.find(c => c.id === prod.id_producto);
if (found) { found.cantidad += qty; }
else { cart.push({ id: prod.id_producto, nombre: prod.nombre, precio: Number(prod.precio), cantidad: qty }); }

const total = cart.reduce((s,c) => s + c.precio * c.cantidad, 0);
const msg = `✅ Agregué <b>${qty}x ${prod.nombre}</b> a tu carrito.\n` +
            `🛒 Items: ${cart.reduce((s,c)=>s+c.cantidad,0)} · Total parcial: 💲${total.toFixed(2)}`;

return [{ json: {
  ok:true, chatId: norm.chatId, userId: norm.userId,
  carrito: JSON.stringify(cart), msg,
  ultimo_cambio: new Date().toISOString().slice(0,19).replace('T',' ')
}}];

// === CONSTRUIR VISTA DEL CARRITO ===
const norm = $('Normalizar Entrada').first().json;
let cart = [];
const sess = $('Leer Sesión (cart)').all().map(i => i.json);
if (sess.length && sess[0].carrito_temporal) {
  try { cart = JSON.parse(sess[0].carrito_temporal); } catch (e) { cart = []; }
}
if (!Array.isArray(cart)) cart = [];

if (cart.length === 0) {
  return [{ json: { vacio:true, text:'🛒 Tu carrito está vacío.\nEscribe /menu para empezar a pedir.', chatId: norm.chatId } }];
}
const lineas = cart.map(c => `• ${c.cantidad}x ${c.nombre} — 💲${(c.precio*c.cantidad).toFixed(2)}`).join('\n');
const total  = cart.reduce((s,c) => s + c.precio*c.cantidad, 0);
const text   = `🛒 <b>Tu carrito</b>\n\n${lineas}\n\n💵 <b>Total: 💲${total.toFixed(2)}</b>`;
return [{ json: { vacio:false, text, chatId: norm.chatId } }];

// === PROCESAR PEDIDO ===
// Re-valida stock contra MENU (otra persona pudo agotarlo) y arma el pedido.
const norm = $('Normalizar Entrada').first().json;
const userId = norm.userId;

let cart = [];
const sess = $('Leer Sesión (confirm)').all().map(i => i.json);
if (sess.length && sess[0].carrito_temporal) {
  try { cart = JSON.parse(sess[0].carrito_temporal); } catch (e) { cart = []; }
}
if (!Array.isArray(cart)) cart = [];

const menu = $('Leer MENU (stock)').all().map(i => i.json);

if (cart.length === 0) {
  return [{ json: { ok:false, reason:'🛒 Tu carrito está vacío. Escribe /menu para pedir.', chatId: norm.chatId } }];
}
// re-chequeo de stock
for (const it of cart) {
  const prod = menu.find(p => String(p.id_producto) === String(it.id));
  if (!prod || Number(prod.stock) < it.cantidad) {
    return [{ json: { ok:false, reason:`⚠️ Ya no hay stock suficiente de <b>${it.nombre}</b>. Ajusta tu carrito (/carrito).`, chatId: norm.chatId } }];
  }
}

const IVA = 0.00; // <-- ajustable (0.19 = 19%)
const subtotal = cart.reduce((s,c) => s + c.precio*c.cantidad, 0);
const total = subtotal * (1 + IVA);

const now = new Date();
const p2 = n => String(n).padStart(2,'0');
const y=now.getFullYear(), m=p2(now.getMonth()+1), d=p2(now.getDate());
const hh=p2(now.getHours()), mm=p2(now.getMinutes()), ss=p2(now.getSeconds());
const idPedido = `ORD-${y}${m}${d}-${hh}${mm}${ss}`;

const resumen = cart.map(c => `• ${c.cantidad}x ${c.nombre} — 💲${(c.precio*c.cantidad).toFixed(2)}`).join('\n');
const stockUpdates = cart.map(c => {
  const prod = menu.find(p => String(p.id_producto) === String(c.id));
  return { id_producto: c.id, stock: Number(prod.stock) - c.cantidad };
});

const userMsg = `✅ <b>¡Pedido confirmado!</b>\n\n🧾 Orden: <code>${idPedido}</code>\n${resumen}\n\n` +
  `💵 Total: <b>💲${total.toFixed(2)}</b>${IVA>0?` (incl. IVA ${(IVA*100).toFixed(0)}%)`:''}\n` +
  `📦 Estado: <b>Recibido</b>\n\nTe avisaremos cuando cambie de estado. ¡Gracias! 🙌`;
const kitchenMsg = `🔔 <b>NUEVO PEDIDO</b>\n🧾 ${idPedido}\n👤 ${norm.firstName} (${userId})\n${resumen}\n💵 Total: 💲${total.toFixed(2)}\n⏱ ${hh}:${mm}`;

return [{ json: {
  ok:true, chatId: norm.chatId,
  id_pedido:idPedido, id_usuario:userId, detalles_pedido:JSON.stringify(cart),
  total_pago:Number(total.toFixed(2)), estado:'Recibido', fecha:`${y}-${m}-${d}`, hora:`${hh}:${mm}`,
  stockUpdates, userMsg, kitchenMsg
}}];

// Expande el array stockUpdates a N items (uno por producto) para
// actualizar el stock en UN solo nodo de Google Sheets (operacion por lote).
const upd = $('Procesar Pedido').first().json.stockUpdates || [];
return upd.map(u => ({ json: { id_producto: u.id_producto, stock: u.stock } }));

// === ESTADO DEL ULTIMO PEDIDO ===
const norm = $('Normalizar Entrada').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id_pedido);
if (rows.length === 0) {
  return [{ json: { text:'🔄 No tienes pedidos activos. Pide algo con /menu.', chatId: norm.chatId } }];
}
const last = rows[rows.length - 1];
const pasos = ['Recibido','Preparación','En camino','Entregado'];
const idx = pasos.indexOf(last.estado);
const barra = pasos.map((p,i) => (i <= idx ? '🟢' : '⚪') + ' ' + p).join('\n');
const text = `🔄 <b>Estado de tu pedido</b>\n🧾 <code>${last.id_pedido}</code>\n\n${barra}\n\n💵 Total: 💲${Number(last.total_pago).toFixed(2)}`;
return [{ json: { text, chatId: norm.chatId } }];

// === PREPARAR CAMBIO DE ESTADO ===
const norm = $('Normalizar Entrada').first().json;
const orderId = norm.arg1;
const estadoRaw = norm.arg2;

const estadoMap = {
  'Preparacion': 'Preparación',
  'En_camino':   'En camino',
  'Entregado':   'Entregado',
  'Cancelado':   'Cancelado'
};
const estadoNombre = estadoMap[estadoRaw] || estadoRaw;

const emojiMap = {
  'Preparación': '🔵', 'En camino': '🚀', 
  'Entregado': '✅', 'Cancelado': '❌'
};
const emoji = emojiMap[estadoNombre] || '📦';

const mensajeExtra = {
  'Preparación': '👨‍🍳 Tu pedido está siendo preparado.',
  'En camino':   '🏃 ¡Ya va en camino!',
  'Entregado':   '¡Gracias por tu pedido! 🙌',
  'Cancelado':   'Lamentamos el inconveniente.'
}[estadoNombre] || '';

const clienteMsg =
  emoji + ' <b>Actualización de tu pedido</b>\n\n' +
  '🧾 Orden: <code>' + orderId + '</code>\n' +
  '📦 Nuevo estado: <b>' + estadoNombre + '</b>\n\n' + mensajeExtra;

return [{ json: {
  orderId,
  estadoNombre,
  clienteMsg,
  kitchenChatId: norm.chatId,
  messageId: norm.messageId
}}];

// === PANEL DE COCINA — 1 mensaje por pedido con botones fijos ===
const norm = $('Normalizar Entrada').first().json;
const filas = $input.all().map(i => i.json).filter(r => r.id_pedido);

const pendientes = ['Recibido', 'Preparación', 'En camino'];
const activos = filas.filter(r => pendientes.includes(r.estado)).slice(-4).reverse();

const siguiente = { 'Recibido':'Preparacion', 'Preparación':'En_camino', 'En camino':'Entregado' };
const etiqueta  = { 'Preparacion':'🔵 En Preparación', 'En_camino':'🚀 En Camino', 'Entregado':'✅ Entregado' };

if (activos.length === 0) {
  return [{ json: {
    chatId: norm.chatId,
    text: '✅ <b>Panel de Cocina</b>\n\nNo hay pedidos pendientes. 🎉',
    btnText: '🔄 Actualizar', btnCallback: 'ADMIN', cancelCallback: 'ADMIN'
  }}];
}

return activos.map(o => {
  let items = []; try { items = JSON.parse(o.detalles_pedido || '[]'); } catch(e) {}
  const resumen = items.map(i => i.cantidad + 'x ' + i.nombre).join(', ') || '—';
  const next = siguiente[o.estado];
  return { json: {
    chatId: norm.chatId,
    text: '🧾 <b>' + o.id_pedido + '</b>\n' +
          '📦 ' + resumen + '\n' +
          '💲 $' + Number(o.total_pago).toFixed(2) + ' · Estado: <b>' + o.estado + '</b>',
    btnText:      next ? etiqueta[next] : '—',
    btnCallback:  next ? 'SETSTATUS:' + o.id_pedido + ':' + next : 'ADMIN',
    cancelCallback: 'SETSTATUS:' + o.id_pedido + ':Cancelado'
  }};
});

// === MIS PEDIDOS === (lectura ya filtrada por id_usuario)
const norm = $('Normalizar Entrada').first().json;
let rows = $input.all().map(i => i.json).filter(r => r.id_pedido);
if (rows.length === 0) {
  return [{ json: { text:'📦 Aún no tienes pedidos. ¡Haz el primero con /menu!', chatId: norm.chatId } }];
}
rows = rows.slice(-5).reverse();   // ultimos 5
const emoji = { 'Recibido':'🟡','Preparación':'🔵','En camino':'🟠','Entregado':'🟢','Cancelado':'🔴' };
const lineas = rows.map(r => `${emoji[r.estado]||'•'} <code>${r.id_pedido}</code> — 💲${Number(r.total_pago).toFixed(2)} — <b>${r.estado}</b> (${r.fecha})`).join('\n');
return [{ json: { text:`📦 <b>Tus últimos pedidos</b>\n\n${lineas}`, chatId: norm.chatId } }];

// === VERIFICAR STOCK CRÍTICO ===
// Busca el nombre del producto en MENU (ya leído antes en este mismo flujo).

const menu = $('Leer MENU (stock)').all().map(i => i.json);
const items = $input.all().map(i => i.json);

return items.map(p => {
  const prod = menu.find(m => String(m.id_producto) === String(p.id_producto));
  const nombre = prod ? prod.nombre : String(p.id_producto);
  const stock  = Number(p.stock);
  return { json: {
    id_producto: p.id_producto,
    nombre,
    stock,
    esCritico: stock <= 3,   // umbral del requerimiento
    esAgotado: stock === 0   // para el bonus
  }};
});
